import { isValidNumber, deLocalizeNumber, translate, getCurrentLocale, localizeNumber } from '@ps-refarch-ux/mfe-utils';
export function validateIsNumber(input, condition, context) {
    //console.log('validating isNumber');
    const result = {
        isValid: input === '' || input == null || isValidNumber(input)
    };
    if (result.isValid) {
        context.parsedNumber = deLocalizeNumber(input);
    }
    else {
        result.errorMessage = translate('neon|validation engine|Must be a number');
    }
    //console.log('result: ' + result.isValid);
    return result;
}
export function validateIsInteger(input, condition, context) {
    // an integer string should have no chars that aren't numeric, except an optional negative sign at start
    //console.log('validating integer');
    //At this point we should already know that it is a number.
    //So then it's just a matter of whether it's a
    const result = {
        isValid: input.indexOf(getCurrentLocale().NUMBER_FORMATS.DECIMAL_SEP) === -1
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|xx is not a valid integer.', { input: input });
    }
    //console.log(`result: ${result.isValid}`);
    return result;
}
export function validateMaxNumberValue(input, maxValue, context) {
    //console.log('validating max number');
    const result = {
        isValid: context.parsedNumber <= maxValue
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|The number must be less than or equal to xx', {
            maxValue: localizeNumber(maxValue)
        });
    }
    //console.log('result: ' + result.isValid);
    return result;
}
