export function validateMaxDecimals(input, maxDecimals, context) {
    const countDecimals = function (value) {
        if ((value % 1) === 0) {
            //integer
            return 0;
        }
        return value.toString().split('.')[1].length;
    };
    //console.log('validating max decimals');
    const result = {
        isValid: countDecimals(context.parsedNumber) <= maxDecimals
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|the number cannot exceed xx decimal places.', { maxDecimals: maxDecimals });
    }
    //console.log('result: ' + result.isValid);
    return result;
}
